      showToast(state, 'Ammo +18');
    } else if (pk.kind === 'health') {
      p.hp = Math.min(PLAYER.maxHp, p.hp + 40);
      showToast(state, 'Health +40');
    } else if (pk.kind === 'cash') {
      state.cash += 50;
      showToast(state, 'Found $50 on the street');
      if (audio) audio.cash();
      state.pickups.splice(i, 1);
      continue;
