    if (ped.state === 'down') continue;
    if (dist(hx, hy, ped.x, ped.y) < 26) {
      ped.hp -= PLAYER.punchDamage;
      ped.state = 'flee';
      ped.panic = 3;
      hitAnyone = true;
      if (ped.hp <= 0) {
        ped.state = 'down';
        ped.down = 8;
