    }
  }
  for (const cop of state.cops) {
    if (dist(hx, hy, cop.x, cop.y) < 26) {
      cop.hp -= PLAYER.punchDamage;
      hitAnyone = true;
      addCrime(state, 18, 'You hit a cop!');
      burst(state, cop.x, cop.y, '#3d7ad9', 8, 110);
      if (cop.hp <= 0) cop.down = true;
