          burst(state, cop.x, cop.y, '#3d7ad9', 8, 120);
          if (cop.hp <= 0) cop.down = true;
          dead = true;
          break;
        }
      }
    }
    if (!dead) {
      for (const car of state.cars) {
        if (dist(b.x, b.y, car.x, car.y) < 26) {
