          burst(state, b.x, b.y, '#ffd76a', 5, 100);
          if (car.hp <= 0 && car.driver !== 'player') {
            car.driver = 'parked';
            car.speed = 0;
            burst(state, car.x, car.y, '#888888', 16, 160);
            if (audio) audio.crash();
          }
          dead = true;
          break;
        }
      }
    }
    if (dead) state.bullets.splice(i, 1);
